pub unsafe extern "C" fn sysmlv2_conv_find_interface(s: *mut Session, h: Handle, name: *const Str, scope: u32, visibility: u32, library: bool, out: *mut Ref) -> Status {
    if s.is_null() || out.is_null() || name.is_null() { return Status::InvalidArg; }
    let s = &mut *s;
    let e = match s.elem(h) { Ok(e) => e, Err(st) => return st };
    if let Err(st) = c::applicable(s, e, "findInterface", &["Type"]) { return st; }
    let name = match read_str(&*name) { Ok(x) => x, Err(st) => return s.fail(st, "findInterface: name is not UTF-8") };
    let scope = match c::scope(s, scope) { Ok(x) => x, Err(st) => return st };
    let visibility = match c::visibility(s, visibility) { Ok(x) => x, Err(st) => return st };
    let result = c::kind_by_name(s, e, &name, scope, visibility, library, "InterfaceUsage");
    let answer = c::answer(s, "findInterface", result);
    read::put_reference(s, "findInterface", answer, &mut *out)
}

